      const r = await tools.structurizr[tool]({ dsl, viewKey });
      out[tool + ":" + viewKey] = (typeof r === "string" ? r.slice(0, 80) : JSON.stringify(r).slice(0, 80));
    } catch (e) { out[tool + ":" + viewKey] = "EXC: " + e; }
  }
}
return out;

